  internal void AppendDrawn(System.Windows.Int32Rect bounds){if(canvas.Page==null)return;CancelAnalysis();if(replaceId.Length==0&&workspace.Active.Regions.Count>=12){canvas.ResetSelection();status.Text="本题已选12个框，请删除多余区域，或将相邻内容合并框选；已有框保留。";return;}if(replaceId.Length==0&&workspace.Regions.Count>=80){foreach(var page in workspace.Pages)workspace.RemoveCandidates(page.Id);if(workspace.Regions.Count>=80){canvas.ResetSelection();status.Text="工作区选区已满，请开始新题；已有框保留。";return;}}string id;if(replaceId.Length>0){id=replaceId;workspace.Replace(id,bounds);replaceId="";}else{id=workspace.AddRegion(canvas.Page.Id,bounds).Id;workspace.Attach(id);}canvas.SelectedId=id;canvas.ResetSelection(false);RefreshBasket(id);status.Text="已保留本题全部 "+workspace.Active.Regions.Count+" 个框。继续拖框会追加；也可继续拍下一页。";}
  void PickCandidate(string id){CancelAnalysis();if(workspace.Active.Regions.Count>=12&&!workspace.Active.Regions.Contains(id)){status.Text="本题已选12个框，请先移除多余区域。";return;}if(!workspace.Active.Regions.Contains(id))workspace.Attach(id);replaceId="";RefreshBasket(id);status.Text="已加入本题；核对题干、图表与选项，可继续补框。";}
  void BeginAdjust(){if(basket.SelectedItem is not Item item){status.Text="请先在右侧选择要调整的框。";return;}CancelAnalysis();replaceId=item.Id;var region=workspace.Regions.Single(r=>r.Id==replaceId);ShowPage(region.PageId);replaceId=item.Id;canvas.ResetSelection();status.Text="正在调整选中的一个框：下一次拖框只替换此框，其他框保持。";}
  void RemoveSelected(){if(basket.SelectedItem is Item item){CancelAnalysis();workspace.Detach(item.Id);replaceId="";canvas.ResetSelection();RefreshBasket();}}
  void Move(int direction){if(basket.SelectedItem is Item item){CancelAnalysis();workspace.Move(item.Id,direction);RefreshBasket(item.Id);}}
  void RotatePage(){if(canvas.Page==null)return;CancelAnalysis();var id=canvas.Page.Id;workspace.Rotate(id);canvas.SelectPage(workspace.Pages.Single(p=>p.Id==id));viewRevision++;replaceId="";RefreshPages(id);status.Text="本页已旋转，原有本页选区明确失效，需要重新选；其他页保留。";StartAnalysis();}
  void LoadFiles(){using(var dialog=new WF.OpenFileDialog{Multiselect=true,Filter="题目照片|*.jpg;*.jpeg;*.png;*.bmp;*.tif;*.tiff"}){if(dialog.ShowDialog(this)!=WF.DialogResult.OK)return;if(workspace.Pages.Count+dialog.FileNames.Length>6)throw new InvalidOperationException("最多6页，请删除不需要的页面或换题。");CancelAnalysis();foreach(var file in dialog.FileNames)workspace.AddFile(file);RefreshPages(workspace.Pages.Last().Id);StartAnalysis();}}
  async Task CaptureNext(){if(capture==null){status.Text="当前入口没有相机回调，请使用“载入图片”补充下一页。";return;}if(workspace.Pages.Count>=6)throw new InvalidOperationException("最多6页。");CancelAnalysis();var token=lifetime.Token;var image=await capture(this,token);if(image==null||IsDisposed)return;token.ThrowIfCancellationRequested();var page=workspace.Add(image.Image,image.Label);RefreshPages(page.Id);StartAnalysis();status.Text="已补拍第"+workspace.Pages.Count+"页；此前选框全部保留，请继续选本页所需区域。";}
  internal void StartAnalysis(){if(!AutoAnalyze||IsDisposed||canvas.Page==null)return;CancelAnalysis();var page=canvas.Page;if(analyzed.TryGetValue(page.Id,out var cached)&&cached.Item1==page.Revision){ApplyAnalysis(page,page.Revision,workspace.Revision,cached.Item2,true);AnalysisTask=Task.CompletedTask;return;}analysis=CancellationTokenSource.CreateLinkedTokenSource(lifetime.Token);var token=analysis.Token;long stamp=workspace.Revision,view=viewRevision;int pageRevision=page.Revision;status.Text="正在本机识别题框，可直接拖框，不必等待；可随时停止自动识别…";AnalysisTask=Analyze(page,pageRevision,stamp,view,analysisGeneration,token);}
  void ApplyAnalysis(QuestionPage page,int revision,long stamp,CandidateResult result,bool cached){var pending=result.Regions.Where(v=>!workspace.Regions.Any(r=>!r.Candidate&&r.PageId==page.Id&&r.Bounds==v.Bounds)).ToArray();if(!workspace.AcceptCandidates(page.Id,revision,stamp,pending))return;canvas.Invalidate();status.Text=result.Message+(cached?" 已复用本页识别结果。":" 用时 "+result.Seconds.ToString("0.0")+"秒。")+" 蓝框需点击确认，手动拖框默认追加。";}
  async Task Analyze(QuestionPage page,int revision,long stamp,long view,long generation,CancellationToken token){try{var result=await CandidateDetector.Detect(page,token);if(IsDisposed||generation!=analysisGeneration||token.IsCancellationRequested||view!=viewRevision||canvas.Page?.Id!=page.Id||workspace.Revision!=stamp)return;if(result.OcrAvailable)analyzed[page.Id]=Tuple.Create(revision,result);ApplyAnalysis(page,revision,stamp,result,false);}catch(OperationCanceledException){if(!IsDisposed&&generation==analysisGeneration&&view==viewRevision&&canvas.Page?.Id==page.Id&&workspace.Revision==stamp)status.Text="自动识别已停止，可直接手动拖框；已有选框保留。";}catch(Exception error){SessionDiagnostics.Record("analysis-ui-error",null,error);if(!IsDisposed)status.Text="本次未识别出可靠题框，可直接拖框；已有选框保留。";}}
  async Task Preview(bool finish){CancelAnalysis();var payload=await workspace.ComposeAsync(high,lifetime.Token);if(IsDisposed||payload.Revision!=workspace.Revision)return;using(var form=new QuietPreview{Text="确认本题 · 只含选中区域",Width=Math.Min(1100,Width),Height=Math.Min(900,Height),StartPosition=WF.FormStartPosition.CenterParent,Font=Font}){if(Entry.OfflineUiTesting){form.StartPosition=WF.FormStartPosition.Manual;form.Location=new Point(-12000,-12000);}var body=new WF.FlowLayoutPanel{Dock=WF.DockStyle.Fill,AutoScroll=true,FlowDirection=WF.FlowDirection.TopDown,WrapContents=false};var controls=Row();controls.Dock=WF.DockStyle.Bottom;var accept=new WF.Button{Text=finish?"确认，开始讲解":"返回继续选题",AutoSize=true,MinimumSize=new Size(200,48)};accept.Click+=(_,__)=>{form.DialogResult=WF.DialogResult.OK;form.Close();};controls.Controls.Add(accept);form.Controls.Add(body);form.Controls.Add(controls);foreach(var image in payload.Images){var bitmap=Raster.ToBitmap(image.Image);int width=Math.Min(950,form.ClientSize.Width-40);body.Controls.Add(new WF.PictureBox{Image=bitmap,Width=width,Height=Math.Max(100,(int)(width*(double)bitmap.Height/bitmap.Width)),SizeMode=WF.PictureBoxSizeMode.Zoom});}try{if(form.ShowDialog(this)==WF.DialogResult.OK&&finish){if(payload.Revision!=workspace.Revision)throw new InvalidOperationException("题图已变化，请重新预览。");Result=payload;DialogResult=WF.DialogResult.OK;Close();}}finally{foreach(var box in body.Controls.OfType<WF.PictureBox>())box.Image?.Dispose();}}}
