 internal sealed class RegionCanvas:WF.Control {
  readonly QuestionWorkspace workspace;Bitmap? image;float zoom=1;PointF offset,start;Point dragStart;bool dragging,panning;internal QuestionPage? Page;internal string SelectedId="";internal System.Windows.Int32Rect Selection;internal event Action? SelectionChanged;internal event Action<System.Windows.Int32Rect>? RegionDrawn;internal event Action<string>? RegionClicked;
  internal RegionCanvas(QuestionWorkspace workspace){this.workspace=workspace;Dock=WF.DockStyle.Fill;DoubleBuffered=true;BackColor=Color.FromArgb(35,39,43);Cursor=WF.Cursors.Cross;MouseWheel+=(_,e)=>Zoom(e.Delta>0?1.2f:1/1.2f);MouseDown+=Down;MouseMove+=Move;MouseUp+=Up;}
  internal RectangleF ImageBounds {get{if(image==null)return RectangleF.Empty;var fit=CropGeometry.Fit(ClientSize,image.Size);float w=fit.Width*zoom,h=fit.Height*zoom;return new RectangleF((ClientSize.Width-w)/2+offset.X,(ClientSize.Height-h)/2+offset.Y,w,h);}}
  internal void SelectPage(QuestionPage? page){Page=page;var old=image;image=page==null?null:Raster.ToBitmap(page.Decode());old?.Dispose();ResetView();ResetSelection();}
  internal void Zoom(float value){zoom=Math.Max(.25f,Math.Min(6,zoom*value));Invalidate();}internal void ResetView(){zoom=1;offset=PointF.Empty;Invalidate();}
  internal void ResetSelection(bool clearId=true){Selection=new System.Windows.Int32Rect();if(clearId)SelectedId="";Invalidate();}
  void Down(object? sender,WF.MouseEventArgs e){if(image==null)return;if(e.Button==WF.MouseButtons.Right){panning=true;dragStart=e.Location;Capture=true;return;}if(e.Button!=WF.MouseButtons.Left||!ImageBounds.Contains(e.Location))return;start=e.Location;dragStart=e.Location;dragging=true;Capture=true;Selection=new System.Windows.Int32Rect();}
  void Move(object? sender,WF.MouseEventArgs e){if(panning){offset.X+=e.X-dragStart.X;offset.Y+=e.Y-dragStart.Y;dragStart=e.Location;Invalidate();return;}if(!dragging||image==null)return;Selection=CropGeometry.Pixels(new RectangleF(start.X,start.Y,e.X-start.X,e.Y-start.Y),ImageBounds,image.Size);SelectedId="";Invalidate();}
  void Up(object? sender,WF.MouseEventArgs e){if(panning){panning=false;Capture=false;return;}if(!dragging||image==null||Page==null)return;dragging=false;Capture=false;if(Math.Abs(e.X-start.X)+Math.Abs(e.Y-start.Y)<10){var b=ImageBounds;int x=(int)((e.X-b.Left)*image.Width/b.Width),y=(int)((e.Y-b.Top)*image.Height/b.Height);SelectedId=workspace.Regions.LastOrDefault(r=>r.PageId==Page.Id&&x>=r.Bounds.X&&y>=r.Bounds.Y&&x<r.Bounds.X+r.Bounds.Width&&y<r.Bounds.Y+r.Bounds.Height)?.Id??"";Selection=new System.Windows.Int32Rect();}else{Selection=CropGeometry.Pixels(new RectangleF(start.X,start.Y,e.X-start.X,e.Y-start.Y),ImageBounds,image.Size);SelectedId="";}SelectionChanged?.Invoke();if(SelectedId.Length>0)RegionClicked?.Invoke(SelectedId);else if(Selection.Width>=32&&Selection.Height>=32)RegionDrawn?.Invoke(Selection);Invalidate();}
  internal Bitmap Thumbnail(System.Windows.Int32Rect r){if(image==null)throw new InvalidOperationException("请先选择页面。");double scale=Math.Min(1,Math.Min(280d/r.Width,140d/r.Height));var result=new Bitmap(Math.Max(1,(int)(r.Width*scale)),Math.Max(1,(int)(r.Height*scale)));using(var graphics=Graphics.FromImage(result)){graphics.Clear(Color.White);graphics.InterpolationMode=System.Drawing.Drawing2D.InterpolationMode.HighQualityBilinear;graphics.DrawImage(image,new Rectangle(0,0,result.Width,result.Height),new Rectangle(r.X,r.Y,r.Width,r.Height),GraphicsUnit.Pixel);}return result;}
  RectangleF View(System.Windows.Int32Rect r){var b=ImageBounds;return new RectangleF(b.Left+r.X*b.Width/image!.Width,b.Top+r.Y*b.Height/image.Height,r.Width*b.Width/image.Width,r.Height*b.Height/image.Height);}
  protected override void OnResize(EventArgs e){base.OnResize(e);dragging=panning=false;Capture=false;Selection=new System.Windows.Int32Rect();Invalidate();}
  protected override void OnPaint(WF.PaintEventArgs e){base.OnPaint(e);if(image==null)return;e.Graphics.DrawImage(image,ImageBounds);foreach(var r in workspace.Regions.Where(r=>r.PageId==Page!.Id)){var b=View(r.Bounds);using(var pen=new Pen(r.Id==SelectedId?Color.Gold:r.Candidate?Color.DeepSkyBlue:Color.LimeGreen,r.Id==SelectedId?4:2)){if(r.Candidate)pen.DashStyle=System.Drawing.Drawing2D.DashStyle.Dash;e.Graphics.DrawRectangle(pen,b.X,b.Y,b.Width,b.Height);}var groups=workspace.Groups.Where(g=>g.Regions.Contains(r.Id)).Select(g=>g.Name);string label=r.Candidate?(r.Confidence<.5?"版面建议 · 需组合":"题框建议 · 请确认"):workspace.Active.Regions.Contains(r.Id)?"已选 "+(workspace.Active.Regions.IndexOf(r.Id)+1):string.Join("/",groups);using(var brush=new SolidBrush(Color.FromArgb(220,255,255,255)))e.Graphics.FillRectangle(brush,b.Left,Math.Max(0,b.Top-25),Math.Max(80,label.Length*15),25);e.Graphics.DrawString(label,Font,Brushes.Black,b.Left,Math.Max(0,b.Top-25));}if(Selection.Width>0){var r=View(Selection);using(var pen=new Pen(Color.Orange,3))e.Graphics.DrawRectangle(pen,r.X,r.Y,r.Width,r.Height);}}
  protected override void Dispose(bool disposing){if(disposing)image?.Dispose();base.Dispose(disposing);}
